input.function:
() => {
  const content = document.querySelector('.container.content');
  const rect = content.getBoundingClientRect();
  const sidenotes = document.querySelectorAll('.sidenote');
  const snData = Array.from(sidenotes).slice(0,3).map(s => ({
    rect: s.getBoundingClientRect(),
    display: getComputedStyle(s).display,
    float: getComputedStyle(s).float,
  }));
  const article = document.querySelector('article') || document.querySelector('.post') || document.querySelector('.post-content');
  return {
    viewport: window.innerWidth,
    content: { x: rect.x, w: rect.width, maxWidth: getComputedStyle(content).maxWidth, paddingRight: getComputedStyle(content).paddingRight },
    contentRight: rect.right,
    spaceToViewport: window.innerWidth - rect.right,
    articleTag: article ? article.tagName + '.' + article.className : 'none',
    articleRect: article ? article.getBoundingClientRect() : null,
    sidenotes: snData,
    contentHTML: content.innerHTML.substring(0, 400),
  };
}

() => {
  const post = document.querySelector('.post');
  // Get the first few children of .post
  const children = Array.from(post.children).slice(0,5).map(c => ({
    tag: c.tagName,
    class: c.className,
    id: c.id,
  }));
  // Check what the post body content div is
  const contentDiv = post.querySelector('.content') || post.querySelector('[class*="content"]');
  return {
    postChildren: children,
    contentDiv: contentDiv ? { tag: contentDiv.tagName, class: contentDiv.className } : null,
    postHTML_start: post.innerHTML.substring(400, 1000),
  };
}

