input.new_string:
@media (min-width: 80em) {
  /* Let content fill available viewport width beside the sidebar */
  .container.content {
    max-width: none;
  }

  /* Reserve a right column for sidenotes */
  .post {
    padding-right: 14rem;
  }

  /* Cap text-content elements at a comfortable reading width, but no wider
     than the post's text column (post width minus the sidenote column). */
  .post > p,
  .post > h2, .post > h3, .post > h4, .post > h5, .post > h6,
  .post > ul, .post > ol, .post > dl,
  .post > blockquote, .post > pre, .post > table,
  .post > hr, .post > .epigraph {
    max-width: min(calc(100% - 14rem), 38rem);
  }

