/* Epigraph */
.epigraph {
  margin: 3em 0;
}
.epigraph > blockquote {
  margin-top: 3em;
  margin-bottom: 3em;
  font-style: italic;
}
.epigraph > blockquote > footer {
  font-style: normal;
}
.epigraph > blockquote > footer > cite {
  font-style: italic;
}

/* Newthought */
.newthought {
  font-variant: small-caps;
  font-size: 1.2em;
}

/* ── Sidenotes / Marginnotes ────────────────────────────────────
   Default (all screens): hidden, click superscript to reveal.
   Wide screens (≥80em / ~1280px): always-visible right-column float.
   ─────────────────────────────────────────────────────────────── */

.sidenote,
.marginnote {
  display: none;
}

.marginnote-ind,
.sidenote-number {
  position: relative;
  vertical-align: baseline;
  user-select: none;
}

label.sidenote-number,
label.marginnote-ind {
  display: inline;
  font-size: 0.78rem;
  top: -0.4rem;
  position: relative;
  cursor: pointer;
  color: var(--link-color);
}

span.sidenote-number,
span.marginnote-ind {
  font-size: 0.8rem;
  color: var(--link-color);
}

.sidenote .code,
.marginnote .code {
  font-size: 0.85rem;
}

.margin-toggle {
  cursor: pointer;
}

input.margin-toggle {
  position: absolute;
  outline: none;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin-left: 5px;
  margin-top: 5px;
  z-index: -100;
}

label:has(+ input.margin-toggle:focus) {
  outline: 5px auto -webkit-focus-ring-color;
  outline-offset: -3px;
}

label.sidenote-number {
  display: inline;
}

label.marginnote-ind {
  display: none;
}

/* Click-to-reveal on narrow screens */
.margin-toggle:checked + .sidenote,
.margin-toggle:checked + .marginnote {
  display: block;
  margin: 0.6rem 0 0.8rem 0;
  padding: 0.5rem 0.75rem;
  border-left: 3px solid var(--link-color);
  font-size: 0.88rem;
  line-height: 1.5;
  color: var(--list-color);
  font-style: italic;
}

/* ── Layout: full-page scroll with sticky sidebar ───────────────
   Poison locks body/content to separate scroll panes. We undo
   that so the page scrolls as a unit, then pin the sidebar with
   position: sticky so it stays visible while the content scrolls.
   ─────────────────────────────────────────────────────────────── */

body {
  overflow: auto;
  height: auto;
}

body > .wrapper {
  height: auto;
  min-height: 100vh;
  align-items: flex-start;
}

@media (min-width: 48em) {
  .sidebar {
    position: sticky;
    top: 0;
    height: 100vh;
    align-self: flex-start;
  }

  /* Remove the independent content scrollbar; clip only horizontal overflow */
  .container.content {
    overflow-y: visible;
    overflow-x: clip;
  }
}

/* Wide math formulas scroll within their block rather than overflowing the page */
.katex-display {
  overflow-x: auto;
}

