input.function:
() => {
  const content = document.querySelector('.container.content');
  const post = document.querySelector('.post');
  const p = document.querySelector('.post > p');
  const contentR = content.getBoundingClientRect();
  const postR = post.getBoundingClientRect();
  const pR = p ? p.getBoundingClientRect() : null;
  return {
    viewport: window.innerWidth,
    contentW: Math.round(contentR.width), contentMax: getComputedStyle(content).maxWidth,
    postW: Math.round(postR.width), postPadR: getComputedStyle(post).paddingRight,
    pW: pR ? Math.round(pR.width) : null, pMax: p ? getComputedStyle(p).maxWidth : null,
    contentStart: Math.round(contentR.left),
  };
}

